package remframework.geometry.discovery.configuration;

import remframework.geometry.discovery.DiscoveryConnection;

import java.util.*;

/** Exact coordinate-free closed orientable manifold validation. */
public final class CombinatorialSurfaceValidator {
    public Validation validate(CombinatorialFaceComplex surface,int expectedEdges,int expectedFaces,
            int expectedDegree,int expectedFaceSize,int expectedEuler){List<String> failures=new ArrayList<>();if(surface.faces().size()!=expectedFaces)failures.add("FACE_COUNT_MISMATCH");Map<Long,Integer> incidence=new HashMap<>();for(List<Integer> face:surface.faces()){if(face.size()!=expectedFaceSize)failures.add("FACE_SIZE_MISMATCH");if(face.size()<3||face.stream().distinct().count()!=face.size())failures.add("INVALID_FACE");for(int i=0;i<face.size();i++){DiscoveryConnection edge=new DiscoveryConnection(face.get(i),face.get((i+1)%face.size()));incidence.merge(edge.undirectedKey(),1,Integer::sum);}}List<DiscoveryConnection> edges=surface.edges();if(edges.size()!=expectedEdges)failures.add("EDGE_COUNT_MISMATCH");if(incidence.values().stream().anyMatch(value->value!=2))failures.add("EDGE_FACE_INCIDENCE_FAILED");List<Set<Integer>> adjacency=new ArrayList<>();for(int i=0;i<surface.vertexCount();i++)adjacency.add(new HashSet<>());for(DiscoveryConnection edge:edges){adjacency.get(edge.firstNodeId()).add(edge.secondNodeId());adjacency.get(edge.secondNodeId()).add(edge.firstNodeId());}if(adjacency.stream().anyMatch(neighbors->neighbors.size()!=expectedDegree))failures.add("DEGREE_MISMATCH");if(!connected(adjacency))failures.add("DISCONNECTED");if(!vertexLinksAreCycles(surface,adjacency))failures.add("INVALID_MANIFOLD_VERTEX");int euler=surface.vertexCount()-edges.size()+surface.faces().size();if(euler!=expectedEuler)failures.add("EULER_CHARACTERISTIC_MISMATCH");return new Validation(failures.isEmpty(),edges,List.copyOf(new LinkedHashSet<>(failures)),euler);}
    private static boolean connected(List<Set<Integer>> adjacency){if(adjacency.isEmpty())return false;boolean[] seen=new boolean[adjacency.size()];ArrayDeque<Integer> queue=new ArrayDeque<>();seen[0]=true;queue.add(0);int count=1;while(!queue.isEmpty())for(int next:adjacency.get(queue.remove()))if(!seen[next]){seen[next]=true;count++;queue.add(next);}return count==adjacency.size();}
    private static boolean vertexLinksAreCycles(CombinatorialFaceComplex surface,List<Set<Integer>> adjacency){for(int vertex=0;vertex<surface.vertexCount();vertex++){Map<Integer,Set<Integer>> link=new HashMap<>();for(int neighbor:adjacency.get(vertex))link.put(neighbor,new HashSet<>());for(List<Integer> face:surface.faces()){int at=face.indexOf(vertex);if(at>=0){int a=face.get(Math.floorMod(at-1,face.size())),b=face.get((at+1)%face.size());link.get(a).add(b);link.get(b).add(a);}}if(link.values().stream().anyMatch(v->v.size()!=2)||!connectedLink(link))return false;}return true;}
    private static boolean connectedLink(Map<Integer,Set<Integer>> link){if(link.isEmpty())return false;Set<Integer> seen=new HashSet<>();ArrayDeque<Integer> q=new ArrayDeque<>();q.add(link.keySet().iterator().next());while(!q.isEmpty()){int v=q.remove();if(seen.add(v))q.addAll(link.get(v));}return seen.size()==link.size();}
    public record Validation(boolean valid,List<DiscoveryConnection> edges,List<String> failures,int eulerCharacteristic){public Validation{edges=List.copyOf(edges);failures=List.copyOf(failures);}}
}
